/**
 * esbuild plugin that rejects imports of banned Node.js modules
 * in server bundles. These modules are blocked in the sandbox.
 */

import type { Plugin } from 'esbuild'

const BANNED_MODULES = new Set([
  'fs',
  'fs/promises',
  'child_process',
  'net',
  'http',
  'https',
  'http2',
  'tls',
  'dgram',
  'cluster',
  'worker_threads',
  'vm',
  'os',
  'path',
  'stream',
  'readline',
  'repl',
  'inspector',
  'v8',
  'perf_hooks',
  'async_hooks',
  'diagnostics_channel',
  'trace_events',
  'wasi',
  'node:fs',
  'node:fs/promises',
  'node:child_process',
  'node:net',
  'node:http',
  'node:https',
  'node:http2',
  'node:tls',
  'node:dgram',
  'node:cluster',
  'node:worker_threads',
  'node:vm',
  'node:os',
  'node:path',
  'node:stream',
])

export function esbuildBlocklistPlugin(): Plugin {
  return {
    name: 'rundot-server-blocklist',
    setup(build) {
      // Intercept all resolve calls
      build.onResolve({ filter: /.*/ }, (args) => {
        const moduleName = args.path
        if (BANNED_MODULES.has(moduleName)) {
          return {
            errors: [
              {
                text: `Module "${moduleName}" is not allowed in server bundles. GameRoom code runs in a sandboxed environment without access to Node.js built-in modules.`,
                detail: `Banned modules: ${Array.from(BANNED_MODULES).filter(m => !m.startsWith('node:')).join(', ')}`,
              },
            ],
          }
        }
        return undefined
      })
    },
  }
}
